function avatar(c,size){if(c&&c.a)return `<img class="ava" src="app/clubs/${esc(c.a)}" alt="" width="${size}" height="${size}" loading="lazy">`;
  const w=(c?c.n:"?").replace(/ at UCLA|UCLA|—.*$/g,"").split(/[\s/&]+/).filter(x=>x&&!/^(of|the|and|for|at)$/i.test(x));
  const ini=(w.length>1?w[0][0]+w[1][0]:(w[0]||"?").slice(0,2)).toUpperCase();
  return `<span class="ava ini" style="background:${c&&GROUPC[c.g]||"#F9437D"};width:${size}px;height:${size}px;font-size:${Math.round(size*.38)}px" aria-hidden="true">${esc(ini)}</span>`}
