  const hl=el("g",{"pointer-events":"none","aria-hidden":"true",style:"mix-blend-mode:multiply"},map),seen=new Map();
  (ex?visibleSpots().map(x=>[x.p,x.kind==="sparko"]):dayEvents(S.day).map(e=>[e.p,true])).forEach(([p,strong])=>{if(p&&PLACES[p])seen.set(p,seen.get(p)||strong)});
  seen.forEach((strong,k)=>{
    if(FOOT[k])el("path",{d:FOOT[k],fill:strong?"#FFB07F":"#FFD3B0","fill-opacity":.95,stroke:"#F0844F","stroke-width":2.2,"stroke-linejoin":"round"},hl);
    else{const p=PLACES[k];el("circle",{cx:p.x,cy:p.y,r:24,fill:"#FF9E6B","fill-opacity":.38,stroke:"#F0844F","stroke-width":1.5,"stroke-dasharray":"4 4"},hl)}});
