      el("path",{d:"M0 -13 L3.2 -6.5 10.3 -5.5 5.1 -0.6 6.4 6.5 0 3.1 -6.4 6.5 -5.1 -0.6 -10.3 -5.5 -3.2 -6.5Z",fill:p.got?"#fff":dp},g);
