/* ---------- Shuffle: two decks. Events (pink): every upcoming event, right = save to My Events.
   Explore (orange): Sparko corners, restrooms and study spots, right = add to To explore. Left passes. ---------- */
const evDeck=()=>EVENTS.filter(e=>e.days.some(d=>d>=FROM));
const shuf=a=>{for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a};
function reshuffle(){S.order=shuf(evDeck().map(e=>e.id))}
function reshuffleX(){S.orderX=shuf(allSpots().map(x=>x.id))}
reshuffle();reshuffleX();
const handleOf=e=>{const h=evHandle(e);return h?"@"+h:e.host};
const deckLeft=()=>S.order.map(id=>EVENTS.find(e=>e.id===id)).filter(e=>e&&!S.saved.has(e.id)&&!S.passed.has(e.id));
const deckLeftX=()=>{const all=allSpots();S.orderX=S.orderX.concat(all.map(x=>x.id).filter(id=>!S.orderX.includes(id)));
  return S.orderX.map(id=>all.find(x=>x.id===id)).filter(x=>x&&!S.toExp.has(x.id)&&!S.passedX.has(x.id))};
