function spotCard(x,top){const K=KIND[x.kind],ti=top?"":'tabindex="-1"',st=x.kind==="sparko"&&STICKERS.find(k=>k.spot===x.id),src=(x.src||[]).map(k=>XSRC[k]).filter(Boolean);
  return `<article class="poster spot ${top?"ptop":"punder"}" data-id="${x.id}" style="--pc:${K.bg};--po:${K.c};--grad:${K.grad}" ${top?`tabindex="0" role="group" aria-label="${esc(x.title)}, ${K.one}. Right arrow adds to To explore, left arrow passes."`:'aria-hidden="true"'}>
  <span class="stamp yes">Explore</span><span class="stamp no">Pass</span>
  <div class="sface">${st?`<img src="${STK+st.img}" alt="" draggable="false">`:`<img src="${KIND[x.kind].img}" alt="${KIND[x.kind].alt}" draggable="false">`}</div>
  <div class="pbody"><span class="pcat">${K.one}${x.mine?" · added by you":""}</span><h4>${esc(x.title)}</h4><dl><dt>Where</dt><dd>${esc(x.where||"")}</dd></dl><p class="pdesc">${esc(x.blurb||"")}</p>
    ${src.length?`<p class="psrc">From ${src.map(q=>esc(q.t)).join(" · ")}</p>`:""}</div>
  <div class="pfoot"><span></span>${x.p?`<button class="pmap" ${ti}>On the map</button>`:""}<button class="pmore" ${ti}>Details</button></div></article>`}
function showOnMap(e){S.tab="map";S.mode="events";S.view="map";S.recOpen=false;const d=e.days.find(x=>x>=FROM);S.day=d===undefined?e.days[0]:d;render();
  if(e.p){const p=PLACES[e.p],wide=innerWidth>=900;centerOn(p.x-(wide?110:0),p.y+(wide?-20:70),wide?640:440)}openEvent(e)}
function showSpotOnMap(x){S.tab="map";S.mode="explore";S.view="map";if(S.exF!=="all"&&!(S.exF==="mine"?x.mine:x.kind===S.exF))S.exF="all";render();
  if(x.p){const p=PLACES[x.p],wide=innerWidth>=900;centerOn(p.x-(wide?110:0),p.y+(wide?-20:70),wide?640:440)}openX(x)}
let shBusy=false;
function decide(id,yes,card){
  if(shBusy)return;const xp=S.shTab==="explore",item=xp?spotById(id):EVENTS.find(x=>x.id===id);if(!item)return;
  const fin=()=>{shBusy=false;if(xp)(yes?S.toExp:S.passedX).add(id);else(yes?S.saved:S.passed).add(id);S.hist.push({xp,id});
    S.shMsg=yes?(xp?`☆ Added to To explore: ${item.title}`:`♥ Saved to My Events: ${item.t}`):`Passed: ${xp?item.title:item.t}`;render()};
  if(card&&!matchMedia("(prefers-reduced-motion: reduce)").matches){shBusy=true;const s=card.querySelector(yes?".yes":".no");if(s)s.style.opacity=1;
    card.style.transition="transform .26s ease-in,opacity .26s";card.style.transform=`translate(${yes?460:-460}px,40px) rotate(${yes?24:-24}deg)`;card.style.opacity=0;setTimeout(fin,240)}
  else fin();
}
function wireCard(card){let sx=0,sy=0,dx=0,drag=false;const id=card.dataset.id,Y=card.querySelector(".yes"),N=card.querySelector(".no");
  const back=()=>{card.style.transition="transform .2s";card.style.transform="";Y.style.opacity=N.style.opacity=0};
  card.addEventListener("pointerdown",e=>{if(shBusy||e.target.closest("a,button"))return;drag=true;sx=e.clientX;sy=e.clientY;dx=0;card.style.transition="none";try{card.setPointerCapture(e.pointerId)}catch(_){}});
  card.addEventListener("pointermove",e=>{if(!drag)return;dx=e.clientX-sx;card.style.transform=`translate(${dx}px,${(e.clientY-sy)*.25}px) rotate(${dx/16}deg)`;
    Y.style.opacity=Math.max(0,Math.min(1,dx/70));N.style.opacity=Math.max(0,Math.min(1,-dx/70))});
  card.addEventListener("pointerup",()=>{if(!drag)return;drag=false;Math.abs(dx)>80?decide(id,dx>0,card):back()});
  card.addEventListener("pointercancel",()=>{if(drag){drag=false;back()}});
  card.addEventListener("keydown",e=>{if(e.target!==card)return;if(e.key==="ArrowRight"){e.preventDefault();decide(id,true,card)}else if(e.key==="ArrowLeft"){e.preventDefault();decide(id,false,card)}});
  if(S.shTab==="explore"){const x=spotById(id);card.querySelector(".pmore").onclick=()=>openX(x);const m=card.querySelector(".pmap");if(m)m.onclick=()=>showSpotOnMap(x)}
  else{const ev=EVENTS.find(x=>x.id===id);card.querySelector(".pmore").onclick=()=>openEvent(ev);const m=card.querySelector(".pmap");if(m)m.onclick=()=>showOnMap(ev)}
}
function renderShuffle(){
  const P=$("shuffle");P.hidden=S.tab!=="shuffle";if(P.hidden)return;
  const xp=S.shTab==="explore";P.classList.toggle("xp",xp);
  const d=xp?deckLeftX():deckLeft(),total=xp?allSpots().length:evDeck().length;
  const got=xp?S.toExp.size:evDeck().filter(e=>S.saved.has(e.id)).length,pas=xp?S.passedX.size:S.passed.size;
  P.innerHTML=`<div class="shhead"><div class="shtabs" role="tablist" aria-label="Deck"><button role="tab" id="shEv" aria-selected="${!xp}">Events</button><button role="tab" id="shXp" aria-selected="${xp}">Explore</button></div><span class="shcount">${d.length} of ${total} left</span></div>
  <p class="shsub">${xp?"Sparko corners, restrooms and study spots, shuffled. Swipe right to add to To explore.":"Every event this week, shuffled. Swipe right to save, left to pass."}</p>
  <div class="deck">${d.length?d.slice(0,2).reverse().map(x=>xp?spotCard(x,x===d[0]):posterCard(x,x===d[0])).join(""):
    `<div class="shend"><img src="app/sparko.webp" alt="" class="skinned"><b>${xp?"You've seen every spot":"That's every event"}</b><p>${got} ${xp?"in To explore":"saved in My Events"}, ${pas} passed.</p>
     <button id="shMine">Open My Events</button>${pas?`<button class="ghost" id="shAgain">Show the ${pas} I passed again</button>`:""}</div>`}</div>
  <p class="shmsg" role="status">${esc(S.shMsg)}</p>
  <div class="shact"><button class="undo" id="shUndo" aria-label="Undo last swipe" ${S.hist.some(h=>h.xp===xp)?"":"disabled"}>↺</button>
    <button class="no" id="shNo" aria-label="Pass" ${d.length?"":"disabled"}>✕</button>
    <button class="yes" id="shYes" aria-label="${xp?"Add to To explore":"Save to My Events"}" ${d.length?"":"disabled"}>${xp?"☆":"♥"}</button></div>`;
  const top=P.querySelector(".poster.ptop");if(top)wireCard(top);
  $("shEv").onclick=()=>{S.shTab="events";S.shMsg="";render()};$("shXp").onclick=()=>{S.shTab="explore";S.shMsg="";render()};
  $("shNo").onclick=()=>top&&decide(top.dataset.id,false,top);
  $("shYes").onclick=()=>top&&decide(top.dataset.id,true,top);
  $("shUndo").onclick=()=>{let i=S.hist.length-1;while(i>=0&&S.hist[i].xp!==xp)i--;if(i<0)return;const h=S.hist.splice(i,1)[0];
    if(xp){S.toExp.delete(h.id);S.passedX.delete(h.id)}else{S.saved.delete(h.id);S.went.delete(h.id);S.passed.delete(h.id)}S.shMsg="Brought back the last card";render()};
  const m=$("shMine");if(m)m.onclick=()=>{S.tab="mine";render()};
  const g=$("shAgain");if(g)g.onclick=()=>{if(xp){S.passedX.clear();reshuffleX()}else{S.passed.clear();reshuffle()}S.hist=S.hist.filter(h=>h.xp!==xp);S.shMsg="";render()};
  applySkinImgs();
}
function celebrate(){
  const c=$("celebrate");const reduce=matchMedia("(prefers-reduced-motion: reduce)").matches;
  const cols=["#FFC9D6","#F9437D","#FF9E6B","#FFD2B8","#BCCBE4","#D6CBEA","#CFE4D2","#EEE5AE","#F3DCC4"];let conf="";
  if(!reduce)for(let i=0;i<28;i++){const a=Math.random()*Math.PI*2,d=90+Math.random()*120;conf+=`<i class="conf" style="background:${cols[i%cols.length]};--dx:${Math.cos(a)*d}px;--dy:${Math.sin(a)*d+60}px;animation-delay:${Math.random()*.15}s"></i>`}
  c.innerHTML=conf+`<div class="card"><img src="app/sparko.webp" alt="" class="skinned"><b>Nice, you went!</b><small>Marked as attended</small></div>`;
  applySkinImgs();c.hidden=false;clearTimeout(celebrate.t);celebrate.t=setTimeout(()=>c.hidden=true,reduce?1400:1700);
}
function applySkin(id){if(!skinOf(id))id="default";S.skin=id;const sk=skinOf(id)||DEFAULT_SKIN;app.classList.toggle("themed",!!sk.map);
  if(skinOf(id)){app.style.setProperty("--pdeep",sk.pdeep);app.style.setProperty("--p1",sk.p1);app.style.setProperty("--p2",sk.p2)}else["--pdeep","--p1","--p2"].forEach(v=>app.style.removeProperty(v));app.style.setProperty("--skinhue",sk.hue);
  applySkinImgs();render();if(!$("scan").hidden)renderScan()}
// with a sticker skin on, Sparko appears as that sticker (Sparko's own colors are never tinted)
const SPARKO_SRC=$("sparkoImg").src;
function applySkinImgs(){const k=skinOf(S.skin)&&STICKERS.find(x=>x.id===S.skin),src=k?STK+k.img:SPARKO_SRC;
  document.querySelectorAll("#sparkoImg,.skinned").forEach(i=>{i.style.filter="";if(i.getAttribute("src")!==src)i.src=src})}
function renderScan(){
  const el2=$("scan");const next=STICKERS.find(k=>!S.stickers.has(k.id));const f=S.lastFound&&STICKERS.find(k=>k.id===S.lastFound);
  const sel=S.selStk&&STICKERS.find(k=>k.id===S.selStk);
  el2.innerHTML=`<div class="scanhead"><h3>Scan a sticker</h3><button id="scanX" aria-label="Close scanner">✕</button></div>
  <div class="viewfinder"><div class="frame"></div><div class="msg">Point your camera at a Campus Corners sticker.<br><span style="opacity:.7">Scanning comes with the iPhone app. Here you can try it out.</span></div></div>
  <button class="simbtn" id="simScan" ${next?"":"disabled"}>${next?"Simulate a scan":"All stickers collected"}</button>
  ${f?`<div class="found">${disc(f)}<span><b>You found ${esc(f.name)}!</b><br>${f.skin?"Its theme is now in your library.":"It's in your library. Its theme is coming soon."}</span></div>`:""}
  <div class="lib"><h4>Sticker Library</h4><p>${S.stickers.size} of ${STICKERS.length} collected. Tap a collected sticker to see its theme.</p>
  <div class="grid">${STICKERS.map(k=>{const got=S.stickers.has(k.id);return `<button class="stk${got?"":" locked"}" data-id="${k.id}" aria-pressed="${S.selStk===k.id}" ${got?"":'aria-disabled="true"'}>${disc(k)}<b>${got?esc(k.name):"Not collected"}</b><small>${got?(S.skin===k.id?"In use":k.skin?"Tap to preview":"Collected"):esc(k.hint)}</small></button>`}).join("")}</div>
  ${sel?`<div class="skinbar"><span><b>${esc(sel.name)}</b> ${sel.skin?"theme":"sticker"}</span>${!sel.skin?`<span style="font-size:12px;color:var(--ink2)">Theme coming soon</span>`:S.skin===sel.id?`<button class="ghost" id="useDef">Back to default</button>`:`<button id="useSkin">Use this theme</button>`}</div>`:(S.skin!=="default"?`<div class="skinbar"><span>Using <b>${esc(STICKERS.find(x=>x.id===S.skin).name)}</b></span><button class="ghost" id="useDef">Back to default</button></div>`:"")}
  </div>`;
  $("scanX").onclick=()=>{el2.hidden=true;S.lastFound=null};
  if(next)$("simScan").onclick=()=>{S.stickers.add(next.id);S.lastFound=next.id;S.selStk=next.id;render();renderScan()};
  el2.querySelectorAll(".stk").forEach(b=>b.onclick=()=>{if(!S.stickers.has(b.dataset.id))return;S.selStk=b.dataset.id;renderScan()});
  const u=$("useSkin");if(u)u.onclick=()=>applySkin(sel.id);
  const d=$("useDef");if(d)d.onclick=()=>{S.selStk=null;applySkin("default")};
  applySkinImgs();
}
function openScan(){closeSheet();S.recOpen=false;render();$("scan").hidden=false;renderScan();$("scanX").focus()}
function closeSheet(){sheet.hidden=true;$("sparko").hidden=!S.tips||S.tab!=="map"||S.view==="list"}

/* ---------- overlays created once: club finder, review editor, add-a-spot form ---------- */
app.insertAdjacentHTML("beforeend",'<div class="scan clubs" id="clubs" hidden role="dialog" aria-modal="true" aria-labelledby="clubsT"></div><div class="rvwrap" id="review" hidden role="dialog" aria-modal="true" aria-labelledby="rvT"></div><div class="scan addspot" id="addspot" hidden role="dialog" aria-modal="true" aria-labelledby="asT"></div>');

/* ---------- clubs: search, follow; followed clubs become filters at the front ---------- */
function openClubs(){closeSheet();const C=$("clubs");
  C.innerHTML=`<div class="scanhead"><h3 id="clubsT">Clubs</h3><button id="clubsX" aria-label="Close">✕</button></div>
  <p class="clubsub">Follow clubs to get a filter for them on the map. Following is saved on this device.</p>
  <label class="csearch"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6"/><path d="m15 15 5 5"/></svg><input id="clubQ" type="search" placeholder="Search ${CLUBS.length} clubs and orgs" value="${esc(S.clubQ)}" autocomplete="off" aria-label="Search clubs"></label>
  <div id="clubList"></div>`;
  C.hidden=false;$("clubsX").onclick=()=>{C.hidden=true;render()};
  const q=$("clubQ");q.oninput=()=>{S.clubQ=q.value;renderClubList()};C.onkeydown=e=>{if(e.key==="Escape"){C.hidden=true;render()}};
  renderClubList();setTimeout(()=>q.focus({preventScroll:true}),30)}
function renderClubList(){
  const L=$("clubList");if(!L)return;const q=S.clubQ.trim().toLowerCase().replace(/^@/,"");
  const match=c=>!q||c.n.toLowerCase().includes(q)||c.h.toLowerCase().includes(q);
  const row=c=>{const ev=clubEvents(c.h),f=S.follow.has(c.h),open=S.clubOpen===c.h;
    return `<div class="crow${open?" open":""}"><button class="cmain" data-h="${c.h}" aria-expanded="${open}">${avatar(c,40)}<span><b>${esc(c.n)}</b><small>@${esc(c.h)}${ev.length?` · <em>${ev.length} event${ev.length>1?"s":""} this week</em>`:""}</small></span></button>
      <button class="follow" data-h="${c.h}" aria-pressed="${f}">${f?"Following":"Follow"}</button>
      ${open?`<div class="cev">${ev.length?ev.map(e=>`<button class="row" data-id="${e.id}"><span class="dot" style="background:${CATS[e.cat].c}">${badge(e.cat)}</span><span><b>${esc(e.t)}</b><span>${dateText(e)} · ${e.time}</span></span></button>`).join(""):`<p class="empty">No events from this club this week yet.</p>`}
        <a class="iglink" href="https://www.instagram.com/${esc(c.h)}/" target="_blank" rel="noopener">Open @${esc(c.h)} on Instagram ↗</a></div>`:""}</div>`};
  const fol=CLUBS.filter(c=>S.follow.has(c.h)&&match(c)),rest=CLUBS.filter(c=>!S.follow.has(c.h)&&match(c));
  rest.sort((a,b)=>clubEvents(b.h).length-clubEvents(a.h).length);
  L.innerHTML=(fol.length?`<div class="msect">Following</div>`+fol.map(row).join(""):"")+(rest.length?`<div class="msect">${q?"Results":"All clubs"}<span>${q?"":"Clubs with events this week first"}</span></div>`+rest.map(row).join(""):"")+(!fol.length&&!rest.length?`<p class="empty">No club matches “${esc(S.clubQ)}”.</p>`:"");
  L.querySelectorAll(".cmain").forEach(b=>b.onclick=()=>{S.clubOpen=S.clubOpen===b.dataset.h?null:b.dataset.h;renderClubList()});
  L.querySelectorAll(".follow").forEach(b=>b.onclick=()=>{const h=b.dataset.h;if(S.follow.has(h)){S.follow.delete(h);S.clubF.delete(h)}else S.follow.add(h);persist();renderClubList()});
  L.querySelectorAll(".row").forEach(b=>b.onclick=()=>{const e=EVENTS.find(x=>x.id===b.dataset.id);$("clubs").hidden=true;showOnMap(e)});
}

/* ---------- reviews: a 1–5 rating and a note, kept on this device (no account) ---------- */
function reviewBlock(id,show){const rv=S.reviews[id];if(!show&&!rv)return"";
  return rv?`<div class="rev"><div class="revtop"><b>Your review</b>${stars(rv.r)}<button class="revedit">Edit</button></div>${rv.t?`<p>${esc(rv.t)}</p>`:""}<small>${esc(rv.d||"")}</small></div>`
    :`<button class="revbtn">☆ Rate &amp; review</button>`}
function wireReview(id,title,sub){const b=sheet.querySelector(".revedit,.revbtn");if(b)b.onclick=()=>openReview(id,title,sub)}
function openReview(id,title,sub,pre){const R=$("review"),old=S.reviews[id];let r=pre||(old?old.r:0);
  R.innerHTML=`<div class="rvcard"><button class="x" id="rvX" aria-label="Close">✕</button><h3 id="rvT">${esc(title)}</h3>${sub?`<p class="rvsub">${esc(sub)}</p>`:""}
    <div class="rvstars" role="radiogroup" aria-label="Rating">${[1,2,3,4,5].map(n=>`<button role="radio" data-n="${n}" aria-checked="${n===r}" aria-label="${n} star${n>1?"s":""}">★</button>`).join("")}</div>
    <textarea id="rvText" maxlength="600" rows="4" placeholder="What was it like? (optional)">${esc(old?old.t:"")}</textarea>
    <p class="rvnote">Saved on this device only. No account needed.</p>
    <div class="rvact">${old?`<button class="ghost" id="rvDel">Delete</button>`:""}<button id="rvSave" ${r?"":"disabled"}>Save review</button></div></div>`;
  R.hidden=false;const paint=()=>R.querySelectorAll(".rvstars button").forEach(b=>{const n=+b.dataset.n;b.classList.toggle("on",n<=r);b.setAttribute("aria-checked",n===r)});paint();
  R.querySelectorAll(".rvstars button").forEach(b=>b.onclick=()=>{r=+b.dataset.n;paint();$("rvSave").disabled=false});
  const close=()=>{R.hidden=true};$("rvX").onclick=close;R.onkeydown=e=>{if(e.key==="Escape")close()};R.onclick=e=>{if(e.target===R)close()};
  $("rvSave").onclick=()=>{if(!r)return;S.reviews[id]={r,t:$("rvText").value.trim().slice(0,600),d:fmt(new Date(),{month:"short",day:"numeric",year:"numeric"})};close();render();if(!sheet.hidden&&S.sheetFn)S.sheetFn()};
  const del=$("rvDel");if(del)del.onclick=()=>{delete S.reviews[id];close();render();if(!sheet.hidden&&S.sheetFn)S.sheetFn()};
  setTimeout(()=>($("rvText")||R.querySelector(".rvstars button")).focus(),30)}

/* ---------- Explore: filter chips, spot sheets, add your own ---------- */
