function reviewsFor(id){const out=[];const mine=S.reviews[id];if(mine)out.push({who:"You",r:mine.r,t:mine.t,d:mine.d,mine:true});return out}
function ratingSummary(id){const rs=reviewsFor(id).filter(x=>x.r);const n=rs.length,avg=n?rs.reduce((a,x)=>a+x.r,0)/n:0;return{n,avg,dist:[5,4,3,2,1].map(k=>rs.filter(x=>x.r===k).length)}}
