  const keep=[cells[0]];let i=0;while(i<cells.length-1){let j=cells.length-1;while(j>i+1&&!clear(cells[i],cells[j]))j--;keep.push(cells[j]);i=j}
  const pts=keep.map(i=>({x:(i%W)*C+C/2,y:(i/W|0)*C+C/2}));pts[0]={x:a.x,y:a.y};pts.push({x:b.x,y:b.y});
